import { useEffect, useState } from 'react';

export type Article = { id: number; title: string };

export type AsyncState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: Error };

export function ArticleList({ url }: { url: string }) {
  const [state, setState] = useState<AsyncState<Article[]>>({ status: 'idle' });

  useEffect(() => {
    let cancelled = false;
    setState({ status: 'loading' });
    fetch(url)
      .then((r) => r.json() as Promise<Article[]>)
      .then((data) => {
        if (!cancelled) setState({ status: 'success', data });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setState({
          status: 'error',
          error: err instanceof Error ? err : new Error(String(err)),
        });
      });
    return () => {
      cancelled = true;
    };
  }, [url]);

  if (state.status === 'idle') return null;
  if (state.status === 'loading') return <p>loading...</p>;
  if (state.status === 'error') return <p>error: {state.error.message}</p>;
  return (
    <ul>
      {state.data.map((a) => (
        <li key={a.id}>{a.title}</li>
      ))}
    </ul>
  );
}
